"""Импорт банковских выписок.

Поддерживаются форматы (колонки ищутся по названию без учёта регистра и
пробелов по краям, в любом порядке, лишние колонки игнорируются):

    nova         date,amount,description               (разделитель ",")
    sfera        Дата;Сумма;Описание                    (разделитель ";")
    sfera_split  Дата;Описание;Приход;Расход            (разделитель ";")

Кодировка — UTF-8 (BOM допустим), иначе cp1251.
"""

from __future__ import annotations

import csv
import datetime as dt
import io
import logging
import os
import re
from collections import Counter
from dataclasses import dataclass, field
from decimal import Decimal
from typing import Callable

from ledger.clock import Clock, SystemClock
from ledger.errors import (
    StatementRowError,
    UnknownFormatError,
    ValidationError,
)
from ledger.models import Transaction, parse_amount, to_money
from ledger.rules import Categorizer, normalize_text
from ledger.storage import MemoryStore

logger = logging.getLogger(__name__)

NOVA_COLUMNS = ("date", "amount", "description")

_SFERA_DATE = re.compile(r"^[0-9]{2}\.[0-9]{2}\.[0-9]{4}$")
_SFERA_AMOUNT = re.compile(r"^[+-]?(?:[0-9]{1,3}(?:[  ][0-9]{3})+|[0-9]+)(?:,[0-9]{1,2})?$")


@dataclass(frozen=True)
class RowError:
    """Ошибка разбора одной строки выписки (line_no — физическая строка файла)."""

    line_no: int
    message: str


@dataclass(frozen=True)
class ImportResult:
    """Итог импорта выписки."""

    format: str
    encoding: str
    added: int
    duplicates: int
    errors: list[RowError] = field(default_factory=list)


def normalize_description(text: str) -> str:
    """Сравнение описаний для дедупликации (то же, что rules.normalize_text)."""
    return normalize_text(text)


# --- разбор значений ---------------------------------------------------------


def _parse_sfera_date(text: str) -> dt.date:
    value = text.strip()
    if not _SFERA_DATE.match(value):
        raise ValidationError(f"invalid date {text!r}")
    try:
        return dt.date(int(value[6:]), int(value[3:5]), int(value[:2]))
    except ValueError as exc:
        raise ValidationError(f"invalid date {text!r}") from exc


def _parse_sfera_amount(text: str) -> Decimal:
    value = text.strip()
    if not _SFERA_AMOUNT.match(value):
        raise ValidationError(f"invalid amount: {text!r}")
    normalized = value.replace(" ", "").replace(" ", "").replace(",", ".")
    return to_money(Decimal(normalized))


def _split_part(text: str, name: str) -> Decimal | None:
    """Колонка Приход/Расход: None для пустой или нулевой, иначе положительная сумма."""
    value = text.strip()
    if not value:
        return None
    if value[0] in "+-":
        raise ValidationError(f"{name} must not have a sign: {text!r}")
    amount = _parse_sfera_amount(value)
    return amount if amount != 0 else None


# Каждая функция получает ячейки по именам колонок и отдаёт (date, amount, description).
Cells = dict[str, str]
Builder = Callable[[Cells], tuple[dt.date, Decimal, str]]


def _build_nova(c: Cells) -> tuple[dt.date, Decimal, str]:
    try:
        date = dt.date.fromisoformat(c["date"].strip())
    except ValueError as exc:
        raise ValidationError(f"invalid date {c['date']!r}") from exc
    return date, parse_amount(c["amount"]), c["description"]


def _build_sfera(c: Cells) -> tuple[dt.date, Decimal, str]:
    return _parse_sfera_date(c["дата"]), _parse_sfera_amount(c["сумма"]), c["описание"]


def _build_sfera_split(c: Cells) -> tuple[dt.date, Decimal, str]:
    date = _parse_sfera_date(c["дата"])
    income = _split_part(c["приход"], "income")
    expense = _split_part(c["расход"], "expense")
    if income is not None and expense is not None:
        raise ValidationError("both income and expense are filled")
    if income is not None:
        return date, income, c["описание"]
    if expense is not None:
        return date, -expense, c["описание"]
    raise ValidationError("neither income nor expense is filled")


@dataclass(frozen=True)
class _Format:
    name: str
    delimiter: str
    columns: tuple[str, ...]
    build: Builder


_FORMATS = {
    f.name: f
    for f in (
        _Format("nova", ",", NOVA_COLUMNS, _build_nova),
        _Format("sfera", ";", ("дата", "сумма", "описание"), _build_sfera),
        _Format("sfera_split", ";", ("дата", "описание", "приход", "расход"), _build_sfera_split),
    )
}


# --- чтение файла ------------------------------------------------------------


def _read_text(path: str | os.PathLike[str]) -> tuple[str, str]:
    with open(path, "rb") as fh:
        data = fh.read()
    try:
        return data.decode("utf-8-sig"), "utf-8"
    except UnicodeDecodeError:
        pass
    try:
        return data.decode("cp1251"), "cp1251"
    except UnicodeDecodeError as exc:
        raise UnknownFormatError("file is neither UTF-8 nor cp1251") from exc


def _is_junk(row: list[str]) -> bool:
    return all(not cell.strip() for cell in row)


def _is_header_junk(row: list[str]) -> bool:
    return all(not cell.strip().strip(",;").strip() for cell in row)


class _Rows:
    """Читает записи CSV, помня физический номер строки начала записи."""

    def __init__(self, text: str, delimiter: str) -> None:
        self._reader = csv.reader(io.StringIO(text, newline=""), delimiter=delimiter)

    def next(self) -> tuple[int, list[str] | csv.Error] | None:
        before = self._reader.line_num
        try:
            row = next(self._reader)
        except StopIteration:
            return None
        except csv.Error as exc:
            if self._reader.line_num == before:
                return None
            return before + 1, exc
        return before + 1, row


def _find_header(rows: _Rows) -> tuple[int, list[str] | csv.Error] | None:
    while True:
        item = rows.next()
        if item is None:
            return None
        row = item[1]
        if isinstance(row, csv.Error) or not _is_header_junk(row):
            return item


def _header_map(fmt: _Format, row: list[str] | csv.Error) -> dict[str, int] | None:
    """Имя колонки -> индекс, если заголовок подходит формату."""
    if isinstance(row, csv.Error):
        return None
    names = [cell.strip().casefold() for cell in row]
    mapping = {}
    for col in fmt.columns:
        if names.count(col) != 1:
            return None
        mapping[col] = names.index(col)
    return mapping


def _open_statement(
    path: str | os.PathLike[str], fmt: str | None
) -> tuple[_Format, str, _Rows, dict[str, int]]:
    if fmt is not None and fmt not in _FORMATS:
        raise UnknownFormatError(f"unknown format {fmt!r}")
    text, encoding = _read_text(path)
    candidates = [_FORMATS[fmt]] if fmt else list(_FORMATS.values())
    matches = []
    first_line: int | None = None
    for candidate in candidates:
        rows = _Rows(text, candidate.delimiter)
        header = _find_header(rows)
        if header is None:
            continue
        if first_line is None:
            first_line = header[0]
        mapping = _header_map(candidate, header[1])
        if mapping is not None:
            matches.append((candidate, rows, mapping))
    if not matches:
        if first_line is None:
            raise UnknownFormatError("empty statement: no header found")
        wanted = f" for format {fmt!r}" if fmt else ""
        raise UnknownFormatError(f"unrecognized header{wanted}", line_no=first_line)
    if len(matches) > 1:
        raise UnknownFormatError("ambiguous header", line_no=first_line)
    chosen, rows, mapping = matches[0]
    return chosen, encoding, rows, mapping


def detect_format(path: str | os.PathLike[str]) -> str:
    """Определяет формат выписки по заголовку: "nova", "sfera" или "sfera_split"."""
    return _open_statement(path, None)[0].name


# --- импорт ------------------------------------------------------------------


def import_statement(
    path: str | os.PathLike[str],
    store: MemoryStore,
    *,
    fmt: str | None = None,
    strict: bool = False,
    categorizer: Categorizer | None = None,
    clock: Clock | None = None,
) -> ImportResult:
    """Импортирует выписку в store: сначала разбирает весь файл, затем пишет одной пачкой.

    Дубли (дата, сумма, normalize_description с учётом количества) относительно
    содержимого store до импорта пропускаются. Ошибочные строки попадают в
    ImportResult.errors, а при strict=True первая из них даёт StatementRowError,
    и ничего не записывается.
    """
    clock = clock or SystemClock()
    spec, encoding, rows, mapping = _open_statement(path, fmt)
    width = max(mapping.values()) + 1

    existing = Counter(
        (tx.date, tx.amount, normalize_description(tx.description)) for tx in store.all()
    )
    imported_at = clock.now()
    new: list[Transaction] = []
    errors: list[RowError] = []
    duplicates = 0

    while True:
        item = rows.next()
        if item is None:
            break
        line_no, row = item
        if isinstance(row, csv.Error):
            message = str(row)
        elif _is_junk(row):
            continue
        elif len(row) < width:
            message = "not enough fields"
        else:
            try:
                cells = {col: row[idx] for col, idx in mapping.items()}
                date, amount, description = spec.build(cells)
                tx = Transaction(
                    date=date,
                    amount=amount,
                    description=description.strip(),
                    imported_at=imported_at,
                )
            except (ValidationError, ValueError) as exc:
                message = str(exc)
            else:
                key = (tx.date, tx.amount, normalize_description(tx.description))
                if existing[key] > 0:
                    existing[key] -= 1
                    duplicates += 1
                    continue
                if categorizer is not None:
                    category = categorizer.categorize(tx)
                    if category is not None:
                        tx = Transaction(
                            date=tx.date,
                            amount=tx.amount,
                            description=tx.description,
                            category=category,
                            imported_at=tx.imported_at,
                        )
                new.append(tx)
                continue
        if strict:
            raise StatementRowError(message, line_no=line_no)
        errors.append(RowError(line_no, message))

    if new:
        store.add_many(new)
    logger.info(
        "imported %d transactions from %s (%d duplicates, %d errors)",
        len(new), path, duplicates, len(errors),
    )
    return ImportResult(
        format=spec.name,
        encoding=encoding,
        added=len(new),
        duplicates=duplicates,
        errors=errors,
    )


def import_csv(
    path: str | os.PathLike[str],
    store: MemoryStore,
    categorizer: Categorizer | None = None,
    clock: Clock | None = None,
) -> int:
    """Строго импортирует выписку «Новы» в store и возвращает число добавленных транзакций."""
    result = import_statement(
        path, store, fmt="nova", strict=True, categorizer=categorizer, clock=clock
    )
    return result.added

